-- VOR-3: Aufnahmeverfahren für bereits angelegte Antragsteller.
-- Diese Migration wird ausschließlich versioniert; sie wird durch diesen Auftrag nicht ausgeführt.

alter table public.mitglied add column if not exists aufnahme_status text;
update public.mitglied set aufnahme_status = 'aufgenommen' where aufnahme_status is null;
alter table public.mitglied alter column aufnahme_status set default 'aufgenommen';
alter table public.mitglied alter column aufnahme_status set not null;
alter table public.mitglied drop constraint if exists mitglied_aufnahme_status_chk;
alter table public.mitglied add constraint mitglied_aufnahme_status_chk check (aufnahme_status in ('antrag_offen', 'aufgenommen', 'abgelehnt'));
-- Antragsteller haben bewusst noch kein Eintrittsdatum. Der bisherige Default darf keines vortäuschen.
alter table public.mitglied alter column mitglied_seit drop default;
alter table public.mitglied alter column mitglied_seit drop not null;
create index if not exists ix_mitglied_aufnahme_status_aktiv on public.mitglied(aufnahme_status, aktiv);

-- Ein normaler Portalzugang entsteht erst mit der wirksamen Aufnahme. Die
-- administrativen Rollen bleiben für die technische Antragsbearbeitung nutzbar.
create or replace function public.current_app_user_context()
returns table(user_id uuid, mitglied_id bigint, role text, permission_grants bigint, permission_revocations bigint, is_protected boolean, is_demo_account boolean)
language sql stable security definer set search_path = public, pg_temp as $$
  select au.user_id, au.mitglied_id, au.role, coalesce(au.permission_grants, 0),
         coalesce(au.permission_revocations, 0), coalesce(au.is_protected, false), coalesce(au.is_demo_account, false)
    from public.app_user au join public.mitglied m on m.id=au.mitglied_id and m.auth_user_id=au.user_id
   where au.user_id=auth.uid() and au.mitglied_id is not null and au.mitglied_id>0
     and au.role in ('admin','vorstand','user')
     and (m.aufnahme_status='aufgenommen' or au.role in ('admin','vorstand'));
$$;

create or replace function public.guard_mitglied_aufnahme_status()
returns trigger language plpgsql set search_path = public, pg_temp as $$
begin
  if tg_op = 'UPDATE'
     and old.aufnahme_status in ('antrag_offen','abgelehnt')
     and new.aufnahme_status = 'aufgenommen'
     and current_setting('kgv.mitgliedsaufnahme_abschluss', true) is distinct from '1' then
    raise exception 'Die Aufnahme darf nur über den Vorstandsbeschluss erfolgen' using errcode='42501';
  end if;
  if new.aufnahme_status in ('antrag_offen', 'abgelehnt') then
    if new.aktiv or new.mitglied_seit is not null then
      raise exception 'Offene oder abgelehnte Antragsteller dürfen weder aktiv sein noch ein Eintrittsdatum besitzen' using errcode='23514';
    end if;
  end if;
  return new;
end; $$;
drop trigger if exists trg_mitglied_aufnahme_status on public.mitglied;
create trigger trg_mitglied_aufnahme_status before insert or update of aufnahme_status, aktiv, mitglied_seit on public.mitglied
for each row execute function public.guard_mitglied_aufnahme_status();

-- Keine Funktion wird implizit berechtigt; die Zuordnung erfolgt über die vorhandene Verwaltungsoberfläche.
comment on column public.vereinsfunktion_verwendung.verwendungszweck is
  'Datengetriebener Verwendungszweck, u.a. vertragsunterzeichnung, mitgliedsaufnahme_abstimmung und mitgliedsaufnahme_entscheidung.';

create table public.mitgliedsaufnahme_vorstandsbearbeitung (
  id bigint generated by default as identity primary key,
  kommunikationsvorgang_id bigint not null unique references public.kommunikationsvorgang(id) on delete restrict,
  gestartet_am timestamptz not null default now(), gestartet_von_auth_user_id uuid not null,
  entscheidung text not null default 'offen' check (entscheidung in ('offen','angenommen','abgelehnt')),
  entscheidungsweg text null check (entscheidungsweg in ('einstimmig','vorstandssitzung')),
  sitzungsdatum date null,
  entscheidungsbegruendung text null,
  entschieden_am timestamptz null, entschieden_von_auth_user_id uuid null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  constraint ck_mavb_offen check ((entscheidung='offen' and entscheidungsweg is null and sitzungsdatum is null and entscheidungsbegruendung is null and entschieden_am is null and entschieden_von_auth_user_id is null) or entscheidung <> 'offen'),
  constraint ck_mavb_sitzung check (entscheidungsweg is distinct from 'vorstandssitzung' or sitzungsdatum is not null),
  constraint ck_mavb_ablehnung_begruendung check (entscheidung <> 'abgelehnt' or nullif(btrim(entscheidungsbegruendung),'') is not null)
);
create index ix_mavb_offen on public.mitgliedsaufnahme_vorstandsbearbeitung(entscheidung, gestartet_am desc);

create table public.mitgliedsaufnahme_abstimmung_snapshot_person (
  id bigint generated by default as identity primary key,
  vorstandsbearbeitung_id bigint not null references public.mitgliedsaufnahme_vorstandsbearbeitung(id) on delete restrict,
  mitglied_id bigint not null references public.mitglied(id) on delete restrict,
  name_snapshot text not null, snapshot_am timestamptz not null default now(),
  unique(vorstandsbearbeitung_id, mitglied_id)
);
create index ix_maasp_bearbeitung on public.mitgliedsaufnahme_abstimmung_snapshot_person(vorstandsbearbeitung_id);

create table public.mitgliedsaufnahme_abstimmung_snapshot_berechtigung (
  id bigint generated by default as identity primary key,
  snapshot_person_id bigint not null references public.mitgliedsaufnahme_abstimmung_snapshot_person(id) on delete restrict,
  berechtigungsart text not null check (berechtigungsart in ('direkt','vertretung')),
  vereinsfunktion_id bigint not null references public.vereinsfunktion(id) on delete restrict,
  vereinsfunktion_besetzung_id bigint not null references public.vereinsfunktion_besetzung(id) on delete restrict,
  funktion_schluessel_snapshot text not null, funktionsbezeichnung_snapshot text not null,
  vertretung_id bigint null references public.vereinsfunktion_vertretung(id) on delete restrict,
  vertretene_vereinsfunktion_id bigint null references public.vereinsfunktion(id) on delete restrict,
  vertretene_besetzung_id bigint null references public.vereinsfunktion_besetzung(id) on delete restrict,
  vertretene_funktionsbezeichnung_snapshot text null,
  constraint ck_maasb_vertretung check ((berechtigungsart='direkt' and vertretung_id is null and vertretene_vereinsfunktion_id is null and vertretene_besetzung_id is null) or (berechtigungsart='vertretung' and vertretung_id is not null and vertretene_vereinsfunktion_id is not null and vertretene_besetzung_id is not null and nullif(btrim(vertretene_funktionsbezeichnung_snapshot),'') is not null)),
  unique(snapshot_person_id, vereinsfunktion_besetzung_id, vertretung_id)
);
create index ix_maasb_person on public.mitgliedsaufnahme_abstimmung_snapshot_berechtigung(snapshot_person_id);

create table public.mitgliedsaufnahme_abstimmung_stimme (
  id bigint generated by default as identity primary key,
  snapshot_person_id bigint not null references public.mitgliedsaufnahme_abstimmung_snapshot_person(id) on delete restrict,
  version integer not null check (version > 0), stimme text not null check (stimme in ('ja','nein')),
  nein_begruendung text null, abgegeben_von_auth_user_id uuid not null, abgegeben_am timestamptz not null default now(),
  unique(snapshot_person_id, version),
  constraint ck_maas_ja_ohne_grund check (stimme <> 'ja' or nein_begruendung is null)
);
create index ix_maas_aktuell on public.mitgliedsaufnahme_abstimmung_stimme(snapshot_person_id, version desc);

create or replace function public.mitgliedsaufnahme_berechtigungen(p_verwendungszweck text, p_stichtag date default current_date)
returns table(mitglied_id bigint, name_snapshot text, berechtigungsart text, vereinsfunktion_id bigint, vereinsfunktion_besetzung_id bigint, funktion_schluessel text, funktionsbezeichnung text, vertretung_id bigint, vertretene_vereinsfunktion_id bigint, vertretene_besetzung_id bigint, vertretene_funktionsbezeichnung text)
language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
  -- Eine vertretene Besetzung wird genau einmal durch ihren Vertreter ausgeübt.
  if exists (select 1 from public.vereinsfunktion_vertretung v join public.vereinsfunktion_besetzung b on b.id=v.vertretene_besetzung_id join public.vereinsfunktion_verwendung u on u.vereinsfunktion_id=b.vereinsfunktion_id and u.verwendungszweck=p_verwendungszweck where v.gueltig_ab<=p_stichtag and (v.gueltig_bis is null or v.gueltig_bis>=p_stichtag) group by v.vertretene_besetzung_id having count(*)>1) then
    raise exception 'Mehrere gleichzeitig gültige Vertreter für eine stimmberechtigte Besetzung' using errcode='23514';
  end if;
  return query
  with basis as (
    select b.id besetzung_id,b.mitglied_id,f.id funktion_id,f.schluessel,f.bezeichnung
    from public.vereinsfunktion_verwendung u join public.vereinsfunktion f on f.id=u.vereinsfunktion_id and f.aktiv
    join public.vereinsfunktion_besetzung b on b.vereinsfunktion_id=f.id
    where u.verwendungszweck=p_verwendungszweck and b.gueltig_ab<=p_stichtag and (b.gueltig_bis is null or b.gueltig_bis>=p_stichtag)
  ), aufgeloest as (
    select coalesce(rb.mitglied_id,b.mitglied_id) mitglied_id, case when v.id is null then 'direkt' else 'vertretung' end art,
      case when v.id is null then b.funktion_id else rf.id end funktion_id, case when v.id is null then b.besetzung_id else rb.id end ausuebende_besetzung_id,
      case when v.id is null then b.schluessel else rf.schluessel end schluessel, case when v.id is null then b.bezeichnung else rf.bezeichnung end bezeichnung,
      v.id vertretung_id, case when v.id is null then null else b.funktion_id end vertretene_funktion_id, case when v.id is null then null else b.besetzung_id end vertretene_besetzung_id, case when v.id is null then null else b.bezeichnung end vertretene_bezeichnung
    from basis b left join public.vereinsfunktion_vertretung v on v.vertretene_besetzung_id=b.besetzung_id and v.gueltig_ab<=p_stichtag and (v.gueltig_bis is null or v.gueltig_bis>=p_stichtag)
    left join public.vereinsfunktion_besetzung rb on rb.id=v.vertreter_besetzung_id
    left join public.vereinsfunktion rf on rf.id=rb.vereinsfunktion_id and rf.aktiv
  )
  select a.mitglied_id, coalesce(nullif(btrim(concat_ws(' ',m.vorname,m.name)),''),'Mitglied #'||a.mitglied_id), a.art, a.funktion_id,a.ausuebende_besetzung_id,a.schluessel,a.bezeichnung,a.vertretung_id,a.vertretene_funktion_id,a.vertretene_besetzung_id,a.vertretene_bezeichnung from aufgeloest a join public.mitglied m on m.id=a.mitglied_id;
end; $$;

create or replace function public.start_mitgliedsaufnahme_vorstandsbearbeitung(p_kommunikationsvorgang_id bigint)
returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.kommunikationsvorgang%rowtype; b_id bigint; r record; p_id bigint; caller uuid:=auth.uid();
begin
 if caller is null then raise exception 'Authentifizierung erforderlich' using errcode='42501'; end if;
 select * into v from public.kommunikationsvorgang where id=p_kommunikationsvorgang_id for update;
 if not found or v.vorgangstyp<>'vertrag_signatur' or v.dokumenttyp<>'mitgliedsantrag' or v.status<>'letzte_pruefung' or v.final_dokument_id is null or v.signatur_revision is distinct from v.revision then raise exception 'Mitgliedsantrag ist nicht zur Vorstandsbearbeitung bereit' using errcode='23514'; end if;
 select id into b_id from public.mitgliedsaufnahme_vorstandsbearbeitung where kommunikationsvorgang_id=v.id; if found then return b_id; end if;
 if not exists(select 1 from public.dokument d where d.id=v.final_dokument_id and d.archiviert_at is null and d.source_kommunikationsvorgang_id=v.id and d.source_revision=v.revision) then raise exception 'Finaldokument passt nicht zum Vorgang' using errcode='23514'; end if;
 insert into public.mitgliedsaufnahme_vorstandsbearbeitung(kommunikationsvorgang_id,gestartet_von_auth_user_id) values(v.id,caller) returning id into b_id;
 for r in select * from public.mitgliedsaufnahme_berechtigungen('mitgliedsaufnahme_abstimmung',current_date) loop
   insert into public.mitgliedsaufnahme_abstimmung_snapshot_person(vorstandsbearbeitung_id,mitglied_id,name_snapshot) values(b_id,r.mitglied_id,r.name_snapshot) on conflict(vorstandsbearbeitung_id,mitglied_id) do update set name_snapshot=excluded.name_snapshot returning id into p_id;
   insert into public.mitgliedsaufnahme_abstimmung_snapshot_berechtigung(snapshot_person_id,berechtigungsart,vereinsfunktion_id,vereinsfunktion_besetzung_id,funktion_schluessel_snapshot,funktionsbezeichnung_snapshot,vertretung_id,vertretene_vereinsfunktion_id,vertretene_besetzung_id,vertretene_funktionsbezeichnung_snapshot) values(p_id,r.berechtigungsart,r.vereinsfunktion_id,r.vereinsfunktion_besetzung_id,r.funktion_schluessel,r.funktionsbezeichnung,r.vertretung_id,r.vertretene_vereinsfunktion_id,r.vertretene_besetzung_id,r.vertretene_funktionsbezeichnung) on conflict do nothing;
 end loop;
 if not exists(select 1 from public.mitgliedsaufnahme_abstimmung_snapshot_person where vorstandsbearbeitung_id=b_id) then raise exception 'Keine Stimmberechtigten konfiguriert' using errcode='23514'; end if;
 return b_id;
end; $$;

create or replace function public.stimme_mitgliedsaufnahme_ab(p_bearbeitung_id bigint,p_stimme text,p_nein_begruendung text default null)
returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare p_id bigint; v_next integer; v_last record; caller uuid:=auth.uid();
begin
 if caller is null or p_stimme not in ('ja','nein') or (p_stimme='ja' and p_nein_begruendung is not null) then raise exception 'Ungültige Stimmabgabe' using errcode='23514'; end if;
 select sp.id into p_id from public.mitgliedsaufnahme_abstimmung_snapshot_person sp join public.mitgliedsaufnahme_vorstandsbearbeitung b on b.id=sp.vorstandsbearbeitung_id join public.app_user au on au.mitglied_id=sp.mitglied_id and au.user_id=caller where sp.vorstandsbearbeitung_id=p_bearbeitung_id and b.entscheidung='offen' for update;
 if not found then raise exception 'Keine Stimmberechtigung' using errcode='42501'; end if;
 select * into v_last from public.mitgliedsaufnahme_abstimmung_stimme where snapshot_person_id=p_id order by version desc limit 1;
 if found and v_last.stimme=p_stimme and v_last.nein_begruendung is not distinct from nullif(btrim(p_nein_begruendung),'') then return v_last.id; end if;
 select coalesce(max(version),0)+1 into v_next from public.mitgliedsaufnahme_abstimmung_stimme where snapshot_person_id=p_id;
 insert into public.mitgliedsaufnahme_abstimmung_stimme(snapshot_person_id,version,stimme,nein_begruendung,abgegeben_von_auth_user_id) values(p_id,v_next,p_stimme,case when p_stimme='nein' then nullif(btrim(p_nein_begruendung),'') end,caller) returning id into v_next; return v_next;
end; $$;

create or replace function public.entscheide_mitgliedsaufnahme(p_bearbeitung_id bigint,p_ergebnis text,p_weg text,p_sitzungsdatum date default null,p_begruendung text default null,p_aufnahmedatum date default null)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare b public.mitgliedsaufnahme_vorstandsbearbeitung%rowtype; v public.kommunikationsvorgang%rowtype; caller uuid:=auth.uid(); cnt integer; yes_cnt integer;
begin
 if caller is null or p_ergebnis not in ('annehmen','ablehnen') or p_weg not in ('einstimmig','vorstandssitzung') or (p_ergebnis='annehmen' and p_aufnahmedatum is null) then raise exception 'Ungültige Entscheidung oder fehlendes Aufnahmedatum' using errcode='23514'; end if;
 select * into b from public.mitgliedsaufnahme_vorstandsbearbeitung where id=p_bearbeitung_id for update; if not found or b.entscheidung<>'offen' then raise exception 'Bearbeitung ist nicht offen' using errcode='40001'; end if;
 if not exists(select 1 from public.mitgliedsaufnahme_berechtigungen('mitgliedsaufnahme_entscheidung',current_date) x join public.app_user au on au.mitglied_id=x.mitglied_id where au.user_id=caller) then raise exception 'Keine aktuelle Entscheidungsberechtigung' using errcode='42501'; end if;
 if p_weg='vorstandssitzung' and p_sitzungsdatum is null then raise exception 'Sitzungsdatum erforderlich' using errcode='23514'; end if;
 if p_ergebnis='ablehnen' and nullif(btrim(p_begruendung),'') is null then raise exception 'Entscheidungsbegründung erforderlich' using errcode='23514'; end if;
 select * into v from public.kommunikationsvorgang where id=b.kommunikationsvorgang_id for update; if v.status<>'letzte_pruefung' then raise exception 'Kommunikationsvorgang ist nicht abschließbar' using errcode='40001'; end if;
 select count(*),count(*) filter(where s.stimme='ja') into cnt,yes_cnt from public.mitgliedsaufnahme_abstimmung_snapshot_person sp left join lateral(select stimme from public.mitgliedsaufnahme_abstimmung_stimme where snapshot_person_id=sp.id order by version desc limit 1) s on true where sp.vorstandsbearbeitung_id=b.id;
 if p_weg='einstimmig' and (cnt=0 or yes_cnt<>cnt) then raise exception 'Einstimmiger Weg verlangt vollständige Ja-Abstimmung' using errcode='23514'; end if;
 if p_ergebnis='annehmen' then
   perform set_config('kgv.mitgliedsaufnahme_abschluss','1',true);
   update public.mitglied set aufnahme_status='aufgenommen',aktiv=true,mitglied_seit=p_aufnahmedatum where id=v.mitglied_id;
   -- Der bestehende Abschluss bleibt der einzige Weg für Vertreterdaten und erledigt.
   perform public.complete_prepared_mitgliedsantrag_aus_entscheidung(v.id,v.revision,caller,p_aufnahmedatum);
 else
   update public.mitglied set aufnahme_status='abgelehnt',aktiv=false,mitglied_seit=null where id=v.mitglied_id;
   update public.kommunikationsvorgang set status='erledigt',bearbeitet_von=caller where id=v.id;
 end if;
 update public.mitgliedsaufnahme_vorstandsbearbeitung set entscheidung=case when p_ergebnis='annehmen' then 'angenommen' else 'abgelehnt' end,entscheidungsweg=p_weg,sitzungsdatum=p_sitzungsdatum,entscheidungsbegruendung=case when p_ergebnis='ablehnen' then nullif(btrim(p_begruendung),'') else null end,entschieden_am=now(),entschieden_von_auth_user_id=caller,updated_at=now() where id=b.id;
end; $$;

-- Lesemodell; die beiden Views werden über eng geprüfte RLS-Policies abgesichert.
create or replace view public.mitgliedsaufnahme_vorstand_liste with (security_invoker=true) as
select b.id bearbeitung_id,b.kommunikationsvorgang_id,v.mitglied_id,v.final_dokument_id,spc.name_snapshot antragsteller,b.gestartet_am,b.entscheidung,
 count(sp.id) snapshot_personen,count(s.stimme) abgegebene_stimmen,count(s.stimme) filter(where s.stimme='ja') ja_stimmen,count(s.stimme) filter(where s.stimme='nein') nein_stimmen,
 (count(sp.id)>0 and count(s.stimme)=count(sp.id) and count(s.stimme) filter(where s.stimme='ja')=count(sp.id)) einstimmig_ja,
 (count(s.stimme) filter(where s.stimme='nein')>0) konflikt
from public.mitgliedsaufnahme_vorstandsbearbeitung b join public.kommunikationsvorgang v on v.id=b.kommunikationsvorgang_id join public.mitglied m on m.id=v.mitglied_id
left join lateral(select coalesce(nullif(btrim(concat_ws(' ',m.vorname,m.name)),''),'Mitglied #'||m.id) name_snapshot) spc on true
left join public.mitgliedsaufnahme_abstimmung_snapshot_person sp on sp.vorstandsbearbeitung_id=b.id
left join lateral(select stimme from public.mitgliedsaufnahme_abstimmung_stimme where snapshot_person_id=sp.id order by version desc limit 1) s on true group by b.id,v.mitglied_id,v.final_dokument_id,spc.name_snapshot;

alter table public.mitgliedsaufnahme_vorstandsbearbeitung enable row level security;
alter table public.mitgliedsaufnahme_abstimmung_snapshot_person enable row level security;
alter table public.mitgliedsaufnahme_abstimmung_snapshot_berechtigung enable row level security;
alter table public.mitgliedsaufnahme_abstimmung_stimme enable row level security;
create or replace function public.darf_mitgliedsaufnahme_lesen(p_bearbeitung_id bigint)
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from public.mitgliedsaufnahme_abstimmung_snapshot_person sp join public.app_user au on au.mitglied_id=sp.mitglied_id where sp.vorstandsbearbeitung_id=p_bearbeitung_id and au.user_id=auth.uid()) or exists(select 1 from public.mitgliedsaufnahme_berechtigungen('mitgliedsaufnahme_entscheidung',current_date) x join public.app_user au on au.mitglied_id=x.mitglied_id where au.user_id=auth.uid());
$$;

-- Reusable, document-scoped rule for the frozen snapshot and the current
-- decision entitlement. Snapshot access deliberately remains historical.
create or replace function public.can_access_mitgliedsaufnahme_vorstand_document(p_auth_user_id uuid,p_dokument_id bigint)
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(
   select 1
   from public.mitgliedsaufnahme_vorstandsbearbeitung b
   join public.kommunikationsvorgang v on v.id=b.kommunikationsvorgang_id
   join public.dokument d on d.id=v.final_dokument_id
   where d.id=p_dokument_id and d.archiviert_at is null
     and v.vorgangstyp='vertrag_signatur' and v.dokumenttyp='mitgliedsantrag'
     and (
       exists(select 1 from public.mitgliedsaufnahme_abstimmung_snapshot_person sp join public.app_user au on au.mitglied_id=sp.mitglied_id where sp.vorstandsbearbeitung_id=b.id and au.user_id=p_auth_user_id)
       or exists(select 1 from public.mitgliedsaufnahme_berechtigungen('mitgliedsaufnahme_entscheidung',current_date) x join public.app_user au on au.mitglied_id=x.mitglied_id where au.user_id=p_auth_user_id)
     )
 );
$$;

-- Preserve existing owner and administrative policies; this narrow policy only
-- grants access to the final membership application of a board review.
create policy dokument_select_mitgliedsaufnahme_vorstand
on public.dokument for select to authenticated
using (public.can_access_mitgliedsaufnahme_vorstand_document(auth.uid(),id));
create policy mavb_read on public.mitgliedsaufnahme_vorstandsbearbeitung for select to authenticated using(public.darf_mitgliedsaufnahme_lesen(id));
create policy maasp_read on public.mitgliedsaufnahme_abstimmung_snapshot_person for select to authenticated using(public.darf_mitgliedsaufnahme_lesen(vorstandsbearbeitung_id));
create policy maasb_read on public.mitgliedsaufnahme_abstimmung_snapshot_berechtigung for select to authenticated using(exists(select 1 from public.mitgliedsaufnahme_abstimmung_snapshot_person sp where sp.id=snapshot_person_id and public.darf_mitgliedsaufnahme_lesen(sp.vorstandsbearbeitung_id)));
create policy maas_read on public.mitgliedsaufnahme_abstimmung_stimme for select to authenticated using(exists(select 1 from public.mitgliedsaufnahme_abstimmung_snapshot_person sp where sp.id=snapshot_person_id and public.darf_mitgliedsaufnahme_lesen(sp.vorstandsbearbeitung_id)));
revoke all on table public.mitgliedsaufnahme_vorstandsbearbeitung,public.mitgliedsaufnahme_abstimmung_snapshot_person,public.mitgliedsaufnahme_abstimmung_snapshot_berechtigung,public.mitgliedsaufnahme_abstimmung_stimme from public,anon,authenticated;
grant select on public.mitgliedsaufnahme_vorstandsbearbeitung,public.mitgliedsaufnahme_abstimmung_snapshot_person,public.mitgliedsaufnahme_abstimmung_snapshot_berechtigung,public.mitgliedsaufnahme_abstimmung_stimme to authenticated;
grant select on public.mitgliedsaufnahme_vorstand_liste to authenticated;
revoke all on function public.start_mitgliedsaufnahme_vorstandsbearbeitung(bigint),public.stimme_mitgliedsaufnahme_ab(bigint,text,text),public.entscheide_mitgliedsaufnahme(bigint,text,text,date,text,date),public.mitgliedsaufnahme_berechtigungen(text,date),public.darf_mitgliedsaufnahme_lesen(bigint),public.can_access_mitgliedsaufnahme_vorstand_document(uuid,bigint) from public,anon,authenticated;
grant execute on function public.start_mitgliedsaufnahme_vorstandsbearbeitung(bigint),public.stimme_mitgliedsaufnahme_ab(bigint,text,text),public.entscheide_mitgliedsaufnahme(bigint,text,text,date,text,date) to authenticated;
grant execute on function public.can_access_mitgliedsaufnahme_vorstand_document(uuid,bigint) to service_role;

create or replace function public.kann_mitgliedsaufnahme_entscheiden()
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from public.mitgliedsaufnahme_berechtigungen('mitgliedsaufnahme_entscheidung',current_date) x join public.app_user au on au.mitglied_id=x.mitglied_id where au.user_id=auth.uid());
$$;
revoke all on function public.kann_mitgliedsaufnahme_entscheiden() from public;
grant execute on function public.kann_mitgliedsaufnahme_entscheiden() to authenticated;

-- Gemeinsamer, nur intern aufrufbarer Abschlusskern. Der vorhandene service-role
-- Abschluss bleibt bestehen; die Entscheidung verwendet denselben Fachkern.
create or replace function public.complete_prepared_mitgliedsantrag_aus_entscheidung(p_kommunikationsvorgang_id bigint,p_expected_revision integer,p_created_by uuid,p_aufnahmedatum date)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.kommunikationsvorgang%rowtype; d public.dokument%rowtype; rep jsonb; representative_id bigint; current_relation record; start_date date; member_row public.mitglied%rowtype;
begin
 select * into v from public.kommunikationsvorgang where id=p_kommunikationsvorgang_id for update;
 if not found or v.vorgangstyp<>'vertrag_signatur' or v.dokumenttyp<>'mitgliedsantrag' or v.status<>'letzte_pruefung' or v.revision<>p_expected_revision or v.signatur_revision<>p_expected_revision or v.final_dokument_id is null then raise exception 'Der Mitgliedsantrag ist nicht abschließbar' using errcode='40001'; end if;
 select * into d from public.dokument where id=v.final_dokument_id and archiviert_at is null for key share;
 if not found or d.source_kommunikationsvorgang_id is distinct from v.id or d.source_revision is distinct from v.revision then raise exception 'Finaldokument passt nicht zum Vorgang' using errcode='23514'; end if;
 select * into member_row from public.mitglied where id=v.mitglied_id for update; if not found then raise exception 'Mitglied fehlt' using errcode='P0002'; end if;
 if p_aufnahmedatum is null then raise exception 'Aufnahmedatum erforderlich' using errcode='23514'; end if;
 rep:=v.entwurf_daten->'representative'; start_date:=p_aufnahmedatum;
 if rep is not null and jsonb_typeof(rep)='object' then
   if rep->>'mode'='existing' then representative_id:=nullif(rep->>'memberId','')::bigint; if representative_id is null or representative_id=v.mitglied_id or not exists(select 1 from public.mitglied where id=representative_id and aufnahme_status='aufgenommen') then raise exception 'Ungültiger gesetzlicher Vertreter' using errcode='23514'; end if;
   elsif rep->>'mode'='manual' then
     if coalesce(nullif(trim(rep->>'vorname'),''),'')='' or coalesce(nullif(trim(rep->>'nachname'),''),'')='' then raise exception 'Vertreterdaten sind unvollständig' using errcode='23514'; end if;
     insert into public.mitglied(hauptmitglied_id,vorname,name,adresse,plz,ort,mitglied_seit,whatsapp_einwilligung,aktiv,mitglied_ende,aufnahme_status) values(coalesce(member_row.hauptmitglied_id,member_row.id),trim(rep->>'vorname'),trim(rep->>'nachname'),case when coalesce((rep->>'adresseAbweichend')::boolean,false) then trim(rep->>'adresse') else member_row.adresse end,case when coalesce((rep->>'adresseAbweichend')::boolean,false) then trim(rep->>'plz') else member_row.plz end,case when coalesce((rep->>'adresseAbweichend')::boolean,false) then trim(rep->>'ort') else member_row.ort end,start_date,false,true,null,'aufgenommen') returning id into representative_id;
   else raise exception 'Vertretermodus fehlt' using errcode='23514'; end if;
   select * into current_relation from public.mitglied_gesetzlicher_vertreter where minderjaehriges_mitglied_id=v.mitglied_id and gueltig_ab<=start_date and (gueltig_bis is null or gueltig_bis>=start_date) order by (gueltig_bis is null) desc,gueltig_ab desc,id desc limit 1 for update;
   if found and current_relation.vertreter_mitglied_id=representative_id then update public.mitglied_gesetzlicher_vertreter set gueltig_ab=start_date,bemerkung='Automatisch aus Mitgliedsantrag übernommen.',updated_at=now() where id=current_relation.id;
   else if found then update public.mitglied_gesetzlicher_vertreter set gueltig_bis=start_date-1,updated_at=now() where id=current_relation.id; end if; insert into public.mitglied_gesetzlicher_vertreter(minderjaehriges_mitglied_id,vertreter_mitglied_id,gueltig_ab,gueltig_bis,bemerkung,created_at,updated_at) values(v.mitglied_id,representative_id,start_date,null,'Automatisch aus Mitgliedsantrag übernommen.',now(),now()); end if;
 end if;
 update public.kommunikationsvorgang set status='erledigt',bearbeitet_von=p_created_by where id=v.id and status='letzte_pruefung' and revision=p_expected_revision; if not found then raise exception 'Mitgliedsantrag wurde zwischenzeitlich geändert' using errcode='40001'; end if;
end; $$;
revoke all on function public.complete_prepared_mitgliedsantrag_aus_entscheidung(bigint,integer,uuid,date) from public,anon,authenticated;
